import{_ as i,o as a,c as s,ag as d}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"WaitSimDI8421 等待8421码虚拟数字量输入","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/WaitSimDI8421.md","filePath":"3. 指令/4. IO 指令/WaitSimDI8421.md","lastUpdated":1778862643000}'),e={name:"3. 指令/4. IO 指令/WaitSimDI8421.md"};function r(n,t,h,l,p,o){return a(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="waitsimdi8421-等待8421码虚拟数字量输入" tabindex="-1">WaitSimDI8421 等待8421码虚拟数字量输入 <a class="header-anchor" href="#waitsimdi8421-等待8421码虚拟数字量输入" aria-label="Permalink to &quot;WaitSimDI8421 等待8421码虚拟数字量输入&quot;">​</a></h1><p>该指令用于在指定时长内等待一组连续虚拟数字量输入 SimDI 端口的状态组合。在设定时长内若等待条件满足，程序继续向下执行；若设定时长内条件未满足，则超时判断值置为 1 后，程序继续向下执行。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>WaitSimDI8421 (T, INTERENABLE, BEGINPORT, ENDPORT, VALUE, RET, [Goto])</code></p><p><code>WaitSimDI8421(超时时间, 打断使能, 起始虚拟端口, 结束虚拟端口, 目标十进制值, 超时判断值, [跳转行号])</code></p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>T</td><td>int 或 INT 变量</td><td>等待该组虚拟数字量输入 SimDI 信号的时长，单位 ms（0：强制等待直到信号满足）</td><td>必填</td></tr><tr><td>INTERENABLE</td><td>int</td><td>暂停恢复后计时逻辑（0：继续计时，1：重新计时）</td><td>必填</td></tr><tr><td>BEGINPORT</td><td>int</td><td>该段连续 SimDI 端口的起始端口号</td><td>必填</td></tr><tr><td>ENDPORT</td><td>int</td><td>该段连续 SimDI 端口的结束端口号</td><td>必填</td></tr><tr><td>VALUE</td><td>int 或 INT 变量</td><td>目标十进制值，端口组合状态转换后与此值比较</td><td>必填</td></tr><tr><td>RET</td><td>INT</td><td>返回指令执行结束后的状态（0：成功，1：超时）</td><td>必填</td></tr><tr><td>[Goto]</td><td>label</td><td>超时后跳转的 label 名</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitSimDI8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在 1000ms 时长内等待 9 到 16 号 SimDI 口状态为 11111111 时，若满足条件则程序继续向下执行，若 1000ms 内未等到条件满足，则将 INT1 置 1。若等待过程中暂停程序，程序恢复运行后计时将继续。</p>',14)])])}const E=i(e,[["render",r]]);export{m as __pageData,E as default};
